"""QApplication entry point for the ``es-soundtrack-tool`` GUI."""

from __future__ import annotations

import importlib
import logging
import sys

from PySide6.QtWidgets import QApplication

from es_ost.logging_setup import configure_logging

from .main_window import MainWindow

logger = logging.getLogger(__name__)

# Register the compiled Qt resource (generated by pyside6-rcc at build time).
# In a source checkout this module does not exist and the import is skipped.
try:
    importlib.import_module(f"{__package__}.rc_data")
except ImportError:
    pass


def main() -> int:
    configure_logging()
    logger.info("es-soundtrack-tool starting")
    app = QApplication(sys.argv)
    app.setApplicationName("es-soundtrack-tool")
    window = MainWindow()
    window.show()
    logger.info("main window shown")
    exit_code = app.exec()
    logger.info("es-soundtrack-tool exiting (code=%d)", exit_code)
    return exit_code


if __name__ == "__main__":
    raise SystemExit(main())
